-- Settings for the JellyJar Chrome extension, edited in the CRM
-- (Browser Profiles → Extension settings).
--
-- One row (id = 1). When someone downloads the extension, the CRM writes this
-- row into the zip as crm-config.js, so a new download always has the team's
-- current searches and keyword lists. Extensions already installed keep their
-- settings until they are downloaded again.
--
--   searches          ordered list of { label, query, durationSeconds, enabled };
--                     each enabled entry is one Nextdoor search in the rotation,
--                     run for durationSeconds
--   include_keywords  a post must contain one of these to be captured
--   exclude_keywords  posts containing any of these are skipped
--   revision          bumps on every save; the extension applies the keyword
--                     lists again when it sees a new revision
--
-- Seeded with the lists built into JellyJar 7.2.6, so nothing changes until
-- someone edits them. Readable by the roles that can download the extension;
-- only admins and sub-admins can change it.

CREATE TABLE public.extension_settings (
  id smallint PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  searches jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(searches) = 'array'),
  include_keywords text[] NOT NULL DEFAULT '{}',
  exclude_keywords text[] NOT NULL DEFAULT '{}',
  revision integer NOT NULL DEFAULT 1,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL
);

ALTER TABLE public.extension_settings ENABLE ROW LEVEL SECURITY;

CREATE POLICY "extension_settings: read"
ON public.extension_settings FOR SELECT TO authenticated
USING (
  current_user_has_role('admin'::app_role)
  OR current_user_has_role_text('sub_admin')
  OR current_user_has_role_text('scraping')
  OR current_user_has_role_text('acc_handler')
);

CREATE POLICY "extension_settings: update"
ON public.extension_settings FOR UPDATE TO authenticated
USING (current_user_has_role('admin'::app_role) OR current_user_has_role_text('sub_admin'))
WITH CHECK (current_user_has_role('admin'::app_role) OR current_user_has_role_text('sub_admin'));

-- Every save gets a new revision, time and author, whatever the client sends.
CREATE OR REPLACE FUNCTION public.tg_extension_settings_bump()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  NEW.revision := OLD.revision + 1;
  NEW.updated_at := now();
  NEW.updated_by := auth.uid();
  RETURN NEW;
END;
$$;

CREATE TRIGGER extension_settings_bump
BEFORE UPDATE ON public.extension_settings
FOR EACH ROW EXECUTE FUNCTION public.tg_extension_settings_bump();

